INSERT INTO changelog (title, body, created_at) VALUES ('Креативи Meta: плитки без «стрибків»', 'У Meta → Креативи плитка при наведенні більше не роздувається поверх сусідів і не зафарбовує підпис темним — лише трохи піднімається. Якщо картинка від Meta не завантажилась (посилання застаріло), береться інша картка оголошення, а якщо нема — показується «нема прев’ю» замість білого порожнього квадрата. Свіжі картинки підтягуються з синхронізацією Meta (раз на 2 год або «Оновити зараз»).', datetime('now'));
